"""Review five raw record kernels, signed branches and explicit DS overrides."""
import argparse,hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'analysis/tools/python'))
from capstone import Cs,CS_ARCH_X86,CS_MODE_16
ENTRIES=['06C9:5299','06C9:5022','06C9:5446','06C9:4F92','06C9:5B5A']
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();assert not out.exists() and out.is_relative_to(ROOT/'docs/recovery/evidence');image=(ROOT/'analysis/derived/td2ega-v1/TD2EGA.image.bin').read_bytes();sha=hashlib.sha256(image).hexdigest();assert sha=='8db38a02cc318a62b15928e217bb9f935699c6566088c21d32382a1c908a59c4';graph='analysis/flow/indirect-v8/direct-flow.json';g=json.loads((ROOT/graph).read_text());md=Cs(CS_ARCH_X86,CS_MODE_16)
 def view(s,ip):
  i=next(md.disasm(image[s*16+ip:s*16+ip+15],ip,count=1));return {'site':f'{s:04X}:{ip:04X}','bytes':i.bytes.hex(),'text':i.mnemonic+' '+i.op_str}
 observations=[{'entry':f['entry'],**view(0x6c9,ip)} for f in g['functions'] if f['entry'] in ENTRIES for ip in sorted(f['instructions'])];assert len(observations)==267
 expected={0x5299:'8a07',0x52c4:'247f',0x52c6:'98',0x52c7:'d1e0',0x52c9:'d1e0',0x52d1:'7c02',0x52ed:'f6e2',0x52ef:'5b',0x503b:'1bda',0x503d:'7c04',0x4f92:'3e8b5a04',0x4f98:'3e8b5a02',0x4f9e:'7e04',0x5008:'7c04',0x5b5a:'a1c852',0x5b6f:'7d04',0x5bb5:'7e04',0x5bde:'7e04',0x5c24:'7d04'}
 for ip,raw in expected.items():assert image[0x6c90+ip:0x6c90+ip+len(raw)//2].hex()==raw,hex(ip)
 callers=[{'owner':f['entry'],**c} for f in g['functions'] for c in f['calls'] if c['target'] in ENTRIES];assert len(callers)==15;windows=[]
 for c in callers:
  f=next(f for f in g['functions'] if f['entry']==c['owner']);site=int(c['site'][5:],16);windows.append({'caller':c,'instructions':[view(0x6c9,ip) for ip in sorted(f['instructions']) if site-14<=ip<=site+14]})
 # Enumerate all source input bytes: masking then word CBW and two SHLs
 # leave value <=508. The last shift's result/sign/overflow prove JL false.
 for raw in range(256):
  value=(raw&127)*4;assert value<=508 and (value&0x8000)==0 and ((value>>15)^((value>>14)&1))==0
 record={'schema':1,'result':'pass','image_sha256':sha,'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'instruction_observations':observations,'direct_caller_candidates':callers,'caller_instruction_windows':windows,'flow_ledger':graph,'flow_ledger_sha256':hashlib.sha256((ROOT/graph).read_bytes()).hexdigest(),'shift_JL_predicate_checks':256,'facts':['5299 reads four DS record bytes at BX with +10 stride, first sign selects DS3340/42, masks each index7F/wordCBW/twoSHL, reads strided DS347F+4*index and always NEGs AL: JL sees preceding SHL SF=OF=0, MOVs do not redefine FLAGS. Unsigned max DL is then byte-absolute-valued, wordlookup DS32EE+2*DL supplies AL for byte MUL DL with DX=DI. POPBX restores saved AX containing first record byte, not original BX; CF is MUL upper-byte-nonzero.','5022 and5446 use raw ring origins/endwords, -8 stride and low SUB/high SBB; 5022 clobbers BP as a wrapping update count, 5446 loads BP/DI from fields and walks two separate record bases. No sortedness/alignment/count or bounded termination assumed.','4F92 and5B5A use explicit3E DS overrides on BP+SI records, not defaultSS. Signed branch direction differs between first/subsequent and forward/backward comparisons. All low-word borrows and signed overflow are retained; modulo correction and ring-end tests read source-order memory.','All five entries use nearRET consuming2. Only5299 saves AX/popsBX;4F92 updating path saves/restores SI from real SS. Other BP/DI/SI clobbers are raw register contracts. Native budgets stop before documented loop sites with existing prefix state and SS writes.','Fifteen direct sites in five owner bodies recorded; caller windows are source observations, not full FLAGS/DS/SS/writer/lifetime/core closure. Initialized table views may overlap state and DAT-fed storage; original values, units and complete formats unassigned.'],'limits':'Instruction/segment/near-return and 256 shift-predicate checks only; separate from native vectors. Complete parent bodies, transitive context, resource producers/formats/capacity, all field/table writers, alias lifetime/exclusion, otherFLAGS/core and resource-fedP2/P3/device/session/gameplay/fidelity remain open.'};out.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'result':'pass','sites':len(observations),'direct_sites':len(callers),'shift_checks':256}))
if __name__=='__main__':main()
